/** Generated by scaffold-crud-pages. Query hooks for Subjects.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchSubjectsList,
  fetchSubjectsById,
  createSubjects,
  updateSubjects,
  deleteSubjects,
  type FetchSubjectsListParams,
} from '~/services/httpServices/subjectsService';
import type { CreateSubjectsRequest, UpdateSubjectsRequest } from '~/types/subjects';

const DOMAIN = 'subjects';

export function useSubjectsList(params?: FetchSubjectsListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchSubjectsList(params),
  });
}

export function useSubjects(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchSubjectsById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateSubjects() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateSubjectsRequest) => createSubjects(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateSubjects() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateSubjectsRequest }) =>
      updateSubjects(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteSubjects() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteSubjects(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
